### makePlayer
```js
function makePlayer(idx, charId) {
 const char = CHAR_BY_ID[charId] || CHARS[idx];
 return {
   idx, char, x:0, y:0, vx:0, vy:0,
   facing: idx===0?1:-1,
   onGround:true, coyote:0, jumpsLeft:1, jumpBuffer:0,
   hp: maxHpFor(), maxHp: maxHpFor(),
   charging:false, charge:0, throwCd:0, throwAnim:0, catchAnim:0,
   invuln:0, hitstun:0, ko:false, koT:0, koDir:1,
   runPhase:0, blink:rand(1,4), ai:false, aiTimer:rand(.5,1.5), aiMove:0, aiJumpCd:0, aiStrafe:rand(-1,1), aiStrafeTimer:rand(.5,1.5), aiHold:.5, aiCharge:0,
   demo:false, demoT:rand(0,10), demoThrow:rand(1,3),
   throwHeld:false,
 };
}
```
`maxHpFor` uses global profile; fine.

### setupDemo
```js
function resetDemo(){
  if(!players.length || players.length!==2) players=[makePlayer(0,titleChars[0]),makePlayer(1,titleChars[1])];
  players.forEach((p,i)=>{p.char=CHAR_BY_ID[titleChars[i]]; p.hp=p.maxHp=maxHpFor(); p.ko=false; ...; p.x = ...; p.y=floorY; p.facing = i===0?1:-1; p.demo=true; p.ai=true;});
  balls=[];pickups=[];particles=[];floaters=[];
  generatePlatforms();
}
```
When title after menu, reset.

Positions: p1 x = W*0.22, p2 W*0.78, but if arena narrow (390), 86 and 304, panel covers center, may still be behind panel. Fine.

### randomDuo
