### newMatch
```js
function newMatch(mode='2p', chars=null){
  ensureAudio();
  hideAllOverlays();
  state='countdown'; paused=false;
  titleChars = chars || randomDuo();
  players = [makePlayer(0,titleChars[0]), makePlayer(1,titleChars[1])];
  players[1].ai = mode==='bot';
  match = {mode, scores:[0,0], round:1, damageTaken:[0,0], catches:0, hits:0, startTime: gameT, lastMod:null};
  matchEarnings = {coins:0,hits:0,rounds:0,victory:0,ach:0};
  profile.stats.matches++;
  if(profile.stats.matches>=5) unlock('regular');
  unlock('random');
  roundDamage=[0,0];
  el.hud.classList.remove('hidden');
