const { createRequire } = require('node:module');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');

const results = [];
function check(name, ok, detail) {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);
}

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader'],
  });

  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(900);

  const info = () => page.evaluate(() => window.__bonk.info());
  const shot = async (name) => { await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 82 }); };

  check('boot on title screen', (await page.evaluate(() => window.__bonk.state())) === 'title');
  check('default profile gold is 150', (await info()).gold === 150);
  await shot('t-title');

  // ---------- start match ----------
  await page.evaluate(() => { window.__bonk.startWith('2p', ['donut', 'toast']); window.__bonk.play(); });
  await page.waitForTimeout(500);
  let inf = await info();
  check('match enters play', inf.state === 'play', `state=${inf.state}`);
  check('two distinct brawlers', inf.players[0].name !== inf.players[1].name, `${inf.players[0].name} vs ${inf.players[1].name}`);
  check('3 platforms generated', inf.platforms.length === 3);

  // ---------- platform reachability geometry ----------
  const plats = inf.platforms.slice().sort((a, b) => b.y - a.y); // low to high
  const floor = inf.players[0].y;
  const rises = [];
  let prevY = floor, prevX1 = -1e9, prevX2 = 1e9;
  for (const p of plats) {
    rises.push(prevY - p.y);
    const overlap = Math.min(prevX2, p.x + p.w) - Math.max(prevX1, p.x);
    check('platform step clearable & overlapped', prevY - p.y < 165 && (prevX1 === -1e9 || overlap > 20),
      `rise=${Math.round(prevY - p.y)} overlap=${Math.round(prevX1 === -1e9 ? 0 : overlap)}`);
    prevY = p.y; prevX1 = p.x; prevX2 = p.x + p.w;
  }

  // Actually jump onto each platform in sequence.
  const p1 = inf.players[0];
  let landedAll = true;
  for (let i = 0; i < plats.length; i++) {
    const pl = plats[i];
    const tx = pl.x + pl.w / 2;
    await page.evaluate(([cx, x]) => window.__bonk.teleport ? window.__bonk.teleport(0, x, cx) : null, [tx, tx]);
    if (!(await page.evaluate(() => !!window.__bonk.teleport))) {
      // fall back: move horizontally on the ground with keys
      await page.evaluate(() => window.__bonk.teleport ? null : null);
    }
    await page.keyboard.down('KeyW');
    await page.waitForTimeout(90);
    await page.keyboard.up('KeyW');
    await page.waitForTimeout(800);
    const cur = (await info()).players[0];
    const ok = Math.abs(cur.y - pl.y) < 4;
    if (!ok) landedAll = false;
    check(`jump lands on platform ${i + 1}`, ok, `y=${cur.y} target=${pl.y}`);
  }
  await shot('t-platforms');

  // ---------- charging + throw + hit ----------
  await page.evaluate(() => { window.__bonk.teleport(0, 320, 740); window.__bonk.teleport(1, 900, 740); });
  await page.waitForTimeout(150);
  const hpBefore = (await info()).players[1].hp;
  await page.keyboard.down('Space');
  await page.waitForTimeout(650);
  const chargeState = await page.evaluate(() => window.__bonk.info().players[0]);
  check('holding throw charges up', chargeState.charging === true, `charging=${chargeState.charging}`);
  await page.keyboard.up('Space');
  await page.waitForTimeout(1400);
  inf = await info();
  check('throw spawns/lobs a ball at rival', inf.players[1].hp < hpBefore || inf.balls > 0, `p2hp=${inf.players[1].hp} balls=${inf.balls}`);
  await shot('t-throw');

  // ---------- catch ----------
  await page.evaluate(() => { window.__bonk.teleport(0, 430, 740); window.__bonk.teleport(1, 760, 740); });
  await page.waitForTimeout(250);
  const catchesBefore = await page.evaluate(() => window.__bonk.profile().stats.catches || 0);
  await page.evaluate(() => window.__bonk.toss(1, 0.2));
  try {
    await page.waitForFunction(() => {
      const i = window.__bonk.info();
      return i.ballList.some(b => b.owner === 1 && Math.abs(b.x - 430) < 72);
    }, { timeout: 2500, polling: 16 });
  } catch {}
  await page.keyboard.down('Space');
  await page.waitForTimeout(90);
  await page.keyboard.up('Space');
  await page.waitForTimeout(450);
  const catchesAfter = await page.evaluate(() => window.__bonk.profile().stats.catches || 0);
  check('tap-throw catches incoming ball', catchesAfter > catchesBefore, `${catchesBefore} -> ${catchesAfter}`);

  // ---------- KO + round advance ----------
  await page.evaluate(() => window.__bonk.hurt(1, 999));
  await page.waitForTimeout(300);
  inf = await info();
  check('KO ends the round', inf.state === 'roundEnd', `state=${inf.state}`);
  check('round win recorded', inf.scores[0] === 1, `scores=${JSON.stringify(inf.scores)}`);
  await page.waitForTimeout(2700);
  check('next round starts', (await info()).state === 'countdown', `round=${(await info()).round}`);

  // ---------- finish match 3-0 ----------
  for (let i = 0; i < 2; i++) {
    await page.evaluate(() => window.__bonk.play());
    await page.waitForTimeout(250);
    await page.evaluate(() => window.__bonk.skipRound());
    await page.waitForTimeout(2850);
  }
  await page.waitForTimeout(1600);
  inf = await info();
  check('match end reached', inf.state === 'matchEnd', `state=${inf.state}`);
  check('end screen visible', !(await page.locator('#screenEnd').getAttribute('class')).includes('hidden'));
  await shot('t-end');

  // ---------- rematch ----------
  await page.click('#btnRematch');
  await page.waitForTimeout(500);
  inf = await info();
  check('rematch restarts match', inf.state === 'countdown' && inf.scores[0] === 0 && inf.scores[1] === 0, `state=${inf.state}`);

  // ---------- pause / resume ----------
  await page.evaluate(() => window.__bonk.play());
  await page.waitForTimeout(200);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  const paused = await page.evaluate(() => window.__bonk.info().paused);
  const pauseVisible = !(await page.locator('#screenPause').getAttribute('class')).includes('hidden');
  check('Escape pauses game', paused === true && pauseVisible);
  await shot('t-pause');
  await page.click('#btnResume');
  await page.waitForTimeout(250);
  check('resume continues play', (await info()).paused === false);

  // ---------- arcade: buy upgrade ----------
  await page.evaluate(() => window.__bonk.gold(1000));
  await page.evaluate(() => window.__bonk.arcade('upgrades'));
  await page.waitForTimeout(350);
  const upCount = await page.locator('.up-card').count();
  check('arcade lists 4 upgrades', upCount === 4, `count=${upCount}`);
  await shot('t-arcade-upgrades');
  await page.click('[data-buy="speed"]');
  await page.waitForTimeout(350);
  let prof = await page.evaluate(() => window.__bonk.profile());
  check('upgrade purchase applied', prof.upgrades.speed === 1 && prof.gold === 940, `lvl=${prof.upgrades.speed} gold=${prof.gold}`);
  check('shopper achievement unlocked', prof.ach.includes('shopper'));

  // ---------- arcade: unlock brawler ----------
  await page.click('.tab[data-tab="brawlers"]');
  await page.waitForTimeout(450);
  check('brawler tab renders 6 cards', (await page.locator('.char-card').count()) === 6);
  await shot('t-arcade-brawlers');
  await page.click('[data-char-buy="toast"]');
  await page.waitForTimeout(400);
  prof = await page.evaluate(() => window.__bonk.profile());
  check('brawler unlock applied', prof.unlocked.includes('toast') && prof.gold === 790, `gold=${prof.gold}`);

  // ---------- trophies tab ----------
  await page.click('.tab[data-tab="trophies"]');
  await page.waitForTimeout(350);
  check('trophy tab renders 12 achievements', (await page.locator('.trophy-card').count()) === 12);
  await shot('t-arcade-trophies');
  await page.evaluate(() => document.querySelector('#btnArcadeClose').click());
  await page.waitForTimeout(200);

  // ---------- how to ----------
  await page.evaluate(() => window.__bonk.menu());
  await page.waitForTimeout(500);
  await page.click('#btnHow');
  await page.waitForTimeout(350);
  check('how-to overlay opens', !(await page.locator('#screenHow').getAttribute('class')).includes('hidden'));
  await shot('t-how');
  await page.click('#btnHowClose');

  // ---------- mobile ----------
  const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  const mp = await mctx.newPage();
  mp.on('pageerror', e => errors.push('MOBILE PAGEERROR ' + e.message));
  mp.on('console', m => { if (m.type() === 'error') errors.push('MOBILE CONSOLE ' + m.text()); });
  await mp.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await mp.waitForTimeout(1000);
  await mp.screenshot({ path: 'screenshots/m-title.jpg', type: 'jpeg', quality: 82 });
  const titleFit = await mp.evaluate(() => {
    const p = document.querySelector('.title-panel').getBoundingClientRect();
    return p.width <= innerWidth && p.height <= innerHeight + 2;
  });
  check('mobile title fits viewport', titleFit);
  check('touch class applied on mobile', await mp.evaluate(() => document.body.classList.contains('touch')));

  await mp.evaluate(() => { window.__bonk.startWith('bot', ['gloop', 'pickle']); window.__bonk.play(); });
  await mp.waitForTimeout(600);
  const touchVisible = !(await mp.locator('#touch').getAttribute('class')).includes('hidden');
  const padCount = await mp.locator('#touch .tbtn[data-act]').count();
  check('touch pads shown in play', touchVisible && padCount === 8, `buttons=${padCount}`);
  await mp.screenshot({ path: 'screenshots/m-play.jpg', type: 'jpeg', quality: 82 });

  // touch throw works
  const hpBeforeM = await mp.evaluate(() => window.__bonk.info().players[1].hp);
  const throwBtn = mp.locator('.pad.p1 .tbtn.throw');
  await throwBtn.dispatchEvent('pointerdown', { pointerId: 21, pointerType: 'touch', isPrimary: true });
  await mp.waitForTimeout(500);
  await throwBtn.dispatchEvent('pointerup', { pointerId: 21, pointerType: 'touch', isPrimary: true });
  await mp.waitForTimeout(1200);
  const infM = await mp.evaluate(() => window.__bonk.info());
  check('touch throw fires ball', infM.balls > 0 || infM.players[1].hp < hpBeforeM, `balls=${infM.balls}`);

  await mp.evaluate(() => window.__bonk.arcade('upgrades'));
  await mp.waitForTimeout(400);
  await mp.screenshot({ path: 'screenshots/m-arcade.jpg', type: 'jpeg', quality: 82 });
  const arcadeFits = await mp.evaluate(() => {
    const p = document.querySelector('.arcade-panel').getBoundingClientRect();
    return p.width <= innerWidth && p.height <= innerHeight + 2;
  });
  check('mobile arcade fits viewport', arcadeFits);

  check('no page/console errors', errors.length === 0, errors.slice(0, 4).join(' | '));

  const fails = results.filter(r => !r.ok);
  console.log(`\n${results.length - fails.length}/${results.length} checks passed`);
  if (fails.length) console.log('FAILURES:', fails.map(f => f.name).join(', '));
  await browser.close();
  process.exit(fails.length ? 1 : 0);
})().catch(e => { console.error(e); process.exit(1); });

