const { chromium } = require2('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  page.on('pageerror', e => console.log('ERR', e.message));
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await page.evaluate(() => {
    window.__events = [];
    addEventListener('keydown', e => window.__events.push(['down', e.key, e.code, e.repeat]));
    addEventListener('keyup', e => window.__events.push(['up', e.key, e.code, e.repeat]));
    window.__bonk.startWith('2p', ['donut', 'toast']);
    window.__bonk.play();
  });
  await page.waitForTimeout(400);
  const p = await page.evaluate(() => window.__bonk.info().platforms);
  console.log('platforms', JSON.stringify(p));
  const target = p[0];
  await page.evaluate(x => window.__bonk.teleport(0, x, 740), target.x + target.w / 2);
  await page.waitForTimeout(200);
  console.log('before', JSON.stringify((await page.evaluate(() => window.__bonk.info())).players[0]));
  await page.keyboard.down('w');
  for (let i = 0; i < 8; i++) {
    await page.waitForTimeout(100);
    const pl = (await page.evaluate(() => window.__bonk.info())).players[0];
    console.log('t' + i, pl.y, pl.charging);
  }
  await page.keyboard.up('w');
  await page.waitForTimeout(500);
  console.log('after', JSON.stringify((await page.evaluate(() => window.__bonk.info())).players[0]));
  console.log('events', JSON.stringify(await page.evaluate(() => window.__events)));
  await page.screenshot({ path: 'screenshots/debug-jump.jpg', type: 'jpeg', quality: 82 });
  await browser.close();
})();

